import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"6、【讼】 坎下乾上","description":"横渠易说 - 6、【讼】 坎下乾上","frontmatter":{"title":"6、【讼】 坎下乾上","description":"横渠易说 - 6、【讼】 坎下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/008.md","filePath":"zh/classics/hengqu/008.md"}'),t={name:"zh/classics/hengqu/008.md"};function l(n,a,s,c,d,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_6、【讼】-坎下乾上" tabindex="-1">6、【讼】 坎下乾上 <a class="header-anchor" href="#_6、【讼】-坎下乾上" aria-label="Permalink to “6、【讼】 坎下乾上”">​</a></h1><p>彖曰：讼，上刚下险，险而健讼。“讼有孚窒惕中吉”，刚来而得中也。“终凶”，讼不可成也。“利见大人”，尚中正也；“不利涉大川”，入于渊也。</p><h3 id="象曰-天与水违行-讼-君子以作事谋始。" tabindex="-1">象曰：天与水违行，讼，君子以作事谋始。 <a class="header-anchor" href="#象曰-天与水违行-讼-君子以作事谋始。" aria-label="Permalink to “象曰：天与水违行，讼，君子以作事谋始。”">​</a></h3><h3 id="初六-不永所事-小有言-终吉。-象曰-不永所事-讼不可长也。虽小有言-其辨明也。" tabindex="-1">初六，不永所事，小有言，终吉。 象曰：“不永所事”，讼不可长也。虽小有言，其辨明也。 <a class="header-anchor" href="#初六-不永所事-小有言-终吉。-象曰-不永所事-讼不可长也。虽小有言-其辨明也。" aria-label="Permalink to “初六，不永所事，小有言，终吉。 象曰：“不永所事”，讼不可长也。虽小有言，其辨明也。”">​</a></h3><p>初于正应，中有阴阳之间，不无讼。但以阴居下体为柔顺，履险方初，不永所事，其理辨直，故小有言终吉。直一作正。</p><h3 id="九二-不克讼-归而逋其邑人三百户-无眚。-象曰-不克讼-归逋窜也。自下讼上-患至掇也。" tabindex="-1">九二，不克讼，归而逋其邑人三百户，无眚。 象曰：“不克讼”，归逋窜也。自下讼上，患至掇也。 <a class="header-anchor" href="#九二-不克讼-归而逋其邑人三百户-无眚。-象曰-不克讼-归逋窜也。自下讼上-患至掇也。" aria-label="Permalink to “九二，不克讼，归而逋其邑人三百户，无眚。 象曰：“不克讼”，归逋窜也。自下讼上，患至掇也。”">​</a></h3><p>处险体刚，好讼者也，上下二阴俱非己应，理为不直，故不讼。归而逋窜；使其邑人之众无辜被祸，故曰“邑人无眚”。</p><h3 id="六三-食旧德-贞厉-终吉。或从王事无成。-象曰-食旧德-从上吉也。" tabindex="-1">六三，食旧德，贞厉，终吉。或从王事无成。 象曰：“食旧德”，从上吉也。 <a class="header-anchor" href="#六三-食旧德-贞厉-终吉。或从王事无成。-象曰-食旧德-从上吉也。" aria-label="Permalink to “六三，食旧德，贞厉，终吉。或从王事无成。 象曰：“食旧德”，从上吉也。”">​</a></h3><p>履非其位，处险之极，若能不为他累，专应上九，则虽危终吉，故曰“旧德”；以阴居阳，又处成功，必有悔吝，故曰“无成”。</p><h3 id="九四-不克讼-复即命渝-安贞吉。-象曰-复即命渝-安贞不失也。" tabindex="-1">九四，不克讼，复即命渝，安贞吉。 象曰：“复即命渝”，安贞不失也。 <a class="header-anchor" href="#九四-不克讼-复即命渝-安贞吉。-象曰-复即命渝-安贞不失也。" aria-label="Permalink to “九四，不克讼，复即命渝，安贞吉。 象曰：“复即命渝”，安贞不失也。”">​</a></h3><h3 id="九五-讼元吉。-象曰-讼元吉-以中正也。" tabindex="-1">九五，讼元吉。 象曰：“讼元吉”，以中正也。 <a class="header-anchor" href="#九五-讼元吉。-象曰-讼元吉-以中正也。" aria-label="Permalink to “九五，讼元吉。 象曰：“讼元吉”，以中正也。”">​</a></h3><h3 id="上九-或锡之鞶带-终朝三褫之。-象曰-以讼受服-亦不足敬也。" tabindex="-1">上九，或锡之鞶带，终朝三褫之。 象曰：以讼受服，亦不足敬也。 <a class="header-anchor" href="#上九-或锡之鞶带-终朝三褫之。-象曰-以讼受服-亦不足敬也。" aria-label="Permalink to “上九，或锡之鞶带，终朝三褫之。 象曰：以讼受服，亦不足敬也。”">​</a></h3><p>体健而比于三，理为不直，故不克讼。</p>',13)])])}const f=e(t,[["render",l]]);export{p as __pageData,f as default};
